from datetime import datetime, time

class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(self, quiet_start: time = time(22, 0), quiet_end: time = time(7, 0)) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        self.users = {}  # user -> {channel: enabled}
        # Initialize empty preferences for users when added

    def add_user(self, user: str) -> None:
        # Initialize all channels as enabled by default for the user
        self.users[user] = {channel: True for channel in self.CHANNELS}

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        if channel not in self.CHANNELS:
            raise ValueError(f"Channel must be one of {self.CHANNELS}")
        if user not in self.users:
            # If user doesn't exist, add them first with default settings
            self.add_user(user)
        self.users[user][channel] = enabled

    def _is_quiet_time(self, dt: datetime) -> bool:
        """Check if the given datetime falls within quiet hours."""
        current_time = dt.time()

        # Handle case where quiet period spans midnight (e.g., 22:00 to 07:00)
        if self.quiet_start <= self.quiet_end:
            # Quiet hours are within same day (e.g., 09:00 to 17:00)
            return self.quiet_start <= current_time <= self.quiet_end
        else:
            # Quiet hours span midnight (e.g., 22:00 to 07:00)
            return current_time >= self.quiet_start or current_time <= self.quiet_end

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        """Send a message; returns the channels it was delivered to, in CHANNELS order."""
        if user not in self.users:
            return []

        delivered_channels = []

        for channel in self.CHANNELS:
            # Skip if channel is disabled for this user
            if not self.users[user].get(channel, False):
                continue

            # During quiet hours, only email is delivered; sms and push are muted
            if self._is_quiet_time(at) and channel in ("sms", "push"):
                continue

            # Otherwise, deliver via this channel
            delivered_channels.append(channel)

        return delivered_channels
